insert into public.question_options(id,question_id,option_text,sort_order) values ('e6208f7d-a2aa-4201-a4d2-04c3ccd55181','423779d3-dd81-4b6f-a200-a94de8e0d044','Article 14',1),('063f13bf-d97b-4090-bd2e-44838f1b584f','423779d3-dd81-4b6f-a200-a94de8e0d044','Article 17',2),('4b45c9f4-2e92-4baa-af3f-992385b0e211','423779d3-dd81-4b6f-a200-a94de8e0d044','Article 21',3),('c643e301-5af3-489b-b04b-20ec653dc72e','423779d3-dd81-4b6f-a200-a94de8e0d044','Article 32',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('423779d3-dd81-4b6f-a200-a94de8e0d044','063f13bf-d97b-4090-bd2e-44838f1b584f');
