insert into private.question_solutions(question_id,explanation) values ('28259642-760b-4742-8610-d722c46a3355','Article 58 sets the minimum age for the President at 35 years.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1',t.subject_id,t.id,'mcq','What is the normal term of the Lok Sabha?','easy','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-polity';
insert into public.question_options(id,question_id,option_text,sort_order) values ('32c27e0a-cb58-4515-be55-5ac7fdeceff8','7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1','4 years',1),('33fe951e-f44c-470b-b52b-41912ad16901','7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1','5 years',2),('aea29eb3-84de-4a7d-a634-f7a0ec054ef7','7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1','6 years',3),('604e441f-e150-4ee9-acaf-8c7c4838bff6','7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1','Permanent',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1','33fe951e-f44c-470b-b52b-41912ad16901');
insert into private.question_solutions(question_id,explanation) values ('7e55ba3f-04ef-485c-8cb9-28eb1d32e2b1','The Lok Sabha''s normal term is five years unless dissolved earlier.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '0477e981-60c9-405c-ab8a-1489278a20f2',t.subject_id,t.id,'mcq','Fundamental Duties were added to the Constitution by which amendment?','medium','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-polity';
insert into public.question_options(id,question_id,option_text,sort_order) values ('5919bfa3-9f46-40ec-9461-5e047f9a12a7','0477e981-60c9-405c-ab8a-1489278a20f2','24th Amendment',1),('5fc20a3e-8172-48cd-a400-e7059ad616bf','0477e981-60c9-405c-ab8a-1489278a20f2','42nd Amendment',2),('7ba140e9-9564-4a7d-bdcf-5837284dd744','0477e981-60c9-405c-ab8a-1489278a20f2','44th Amendment',3),('2f64afc4-942b-47ed-b084-a65b2b9e4913','0477e981-60c9-405c-ab8a-1489278a20f2','73rd Amendment',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('0477e981-60c9-405c-ab8a-1489278a20f2','5fc20a3e-8172-48cd-a400-e7059ad616bf');
insert into private.question_solutions(question_id,explanation) values ('0477e981-60c9-405c-ab8a-1489278a20f2','The 42nd Amendment (1976) added Fundamental Duties in Part IV-A (Article 51A).');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select 'be78a88a-44f7-476d-810c-6042918b87d4',t.subject_id,t.id,'mcq','Which article provides the Right to Constitutional Remedies?','medium','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-polity';
insert into public.question_options(id,question_id,option_text,sort_order) values ('aa5afded-6ad6-4b43-9f62-92d90669b5f1','be78a88a-44f7-476d-810c-6042918b87d4','Article 19',1),('a5ca1563-6807-4cef-a2e0-364901386cb9','be78a88a-44f7-476d-810c-6042918b87d4','Article 21',2),('49308336-2193-40e7-8e0d-13b05f00d121','be78a88a-44f7-476d-810c-6042918b87d4','Article 32',3),('726797fe-5976-4dbe-879f-82e91b34553f','be78a88a-44f7-476d-810c-6042918b87d4','Article 44',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('be78a88a-44f7-476d-810c-6042918b87d4','49308336-2193-40e7-8e0d-13b05f00d121');
insert into private.question_solutions(question_id,explanation) values ('be78a88a-44f7-476d-810c-6042918b87d4','Article 32 lets citizens approach the Supreme Court to enforce Fundamental Rights. Dr Ambedkar called it the ''heart and soul'' of the Constitution.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '089fbba6-a985-4bdc-81f6-5ab5debc588c',t.subject_id,t.id,'mcq','Who appoints the Chief Justice of India?','easy','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-polity';
insert into public.question_options(id,question_id,option_text,sort_order) values ('59514e87-25d6-4c07-ab1e-02200405cccb','089fbba6-a985-4bdc-81f6-5ab5debc588c','Prime Minister',1),('b3dbf83f-7ade-48f3-8832-4e22cff80912','089fbba6-a985-4bdc-81f6-5ab5debc588c','President',2),('d12c988c-8e6a-4f59-b4e0-80696068d87d','089fbba6-a985-4bdc-81f6-5ab5debc588c','Parliament',3),('70b15721-c08e-4a88-89a5-223cf9a13182','089fbba6-a985-4bdc-81f6-5ab5debc588c','Law Minister',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('089fbba6-a985-4bdc-81f6-5ab5debc588c','b3dbf83f-7ade-48f3-8832-4e22cff80912');
insert into private.question_solutions(question_id,explanation) values ('089fbba6-a985-4bdc-81f6-5ab5debc588c','The President appoints the Chief Justice of India under Article 124.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select 'ad035e31-d264-4278-9f9a-4c3d2f8a353b',t.subject_id,t.id,'mcq','Why is the Rajya Sabha called a permanent house?','medium','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-polity';
insert into public.question_options(id,question_id,option_text,sort_order) values ('85067f6e-712d-4903-85f8-9b882849ad4a','ad035e31-d264-4278-9f9a-4c3d2f8a353b','Its members are nominated for life',1),('95304649-d62a-4262-bf28-a9156351417f','ad035e31-d264-4278-9f9a-4c3d2f8a353b','It cannot be dissolved',2),('02d5895d-3743-47bb-b7cb-13d6e3d4777a','ad035e31-d264-4278-9f9a-4c3d2f8a353b','It meets all year round',3),('8463f5ea-6726-49f5-8fc3-cb89a1633ba3','ad035e31-d264-4278-9f9a-4c3d2f8a353b','Its size never changes',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('ad035e31-d264-4278-9f9a-4c3d2f8a353b','95304649-d62a-4262-bf28-a9156351417f');
insert into private.question_solutions(question_id,explanation) values ('ad035e31-d264-4278-9f9a-4c3d2f8a353b','The Rajya Sabha is never dissolved; about one-third of its members retire every two years.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select 'd9d24b3b-4d6d-401d-bf71-f9a967aae032',t.subject_id,t.id,'mcq','How many Fundamental Rights does the Indian Constitution currently provide?','medium','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-polity';
insert into public.question_options(id,question_id,option_text,sort_order) values ('30db4a1d-3c64-4073-8903-d6b908a33020','d9d24b3b-4d6d-401d-bf71-f9a967aae032','Five',1),('4a0384cb-5883-4455-8c0d-65660c10f67d','d9d24b3b-4d6d-401d-bf71-f9a967aae032','Six',2),('8a917bc5-a0f6-491d-a268-7437eb758f4a','d9d24b3b-4d6d-401d-bf71-f9a967aae032','Seven',3),('694a3cd0-4e8e-4ac4-90ae-5fb0695c0c54','d9d24b3b-4d6d-401d-bf71-f9a967aae032','Eight',4);
insert into private.question_answer_keys(question_id,correct_option_id) values ('d9d24b3b-4d6d-401d-bf71-f9a967aae032','4a0384cb-5883-4455-8c0d-65660c10f67d');
insert into private.question_solutions(question_id,explanation) values ('d9d24b3b-4d6d-401d-bf71-f9a967aae032','There are six. The Right to Property was removed as a Fundamental Right by the 44th Amendment (1978).');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '47b13cef-7bd2-4f41-9bee-7a13a2d62979',t.subject_id,t.id,'mcq','In which year was the Reserve Bank of India established?','medium','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-economy';
