insert into private.question_answer_keys(question_id,correct_option_id) values ('47b13cef-7bd2-4f41-9bee-7a13a2d62979','73041446-758d-4fb0-b80f-1cb8104f247d');
insert into private.question_solutions(question_id,explanation) values ('47b13cef-7bd2-4f41-9bee-7a13a2d62979','The RBI was set up on 1 April 1935 and nationalised in 1949.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '0c63daa6-d75f-469c-ab65-c10fe350adfa',t.subject_id,t.id,'mcq','From which date was GST implemented in India?','easy','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='indian-economy';
