insert into private.question_solutions(question_id,explanation) values ('9cfd1681-ebc5-4ef0-beb1-766608c13ccb','Project Tiger was launched on 1 April 1973 to protect tigers and their habitats.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '49711a49-5067-4712-ab81-061aadba35fc',t.subject_id,t.id,'mcq','World Environment Day is observed on which date?','easy','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='environment';
insert into public.question_options(id,question_id,option_text,sort_order) values ('84635394-8e9c-453e-9478-e92063d048db','49711a49-5067-4712-ab81-061aadba35fc','22 April',1),('8b985822-08f6-4ca4-b9f8-d0657301df26','49711a49-5067-4712-ab81-061aadba35fc','5 June',2),('c1814851-05d0-4822-aa70-87049782013b','49711a49-5067-4712-ab81-061aadba35fc','16 September',3),('6838066b-a915-4377-8b71-7749356c6606','49711a49-5067-4712-ab81-061aadba35fc','11 December',4);
