insert into private.question_solutions(question_id,explanation) values ('a3ce1920-9d8a-470c-a040-2e70e0a39c37','In the Chipko Movement (1970s, in present-day Uttarakhand), villagers hugged trees to stop them being cut.');
insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '81dbb470-e882-49f7-aca7-08655be017b9',t.subject_id,t.id,'mcq','Which is the largest mangrove forest in the world?','easy','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='environment';
