insert into public.questions(id,subject_id,topic_id,question_type,prompt,difficulty,status,marks,negative_marks,language_code) select '8aa95653-5167-487e-8b21-24cb34a280bb',t.subject_id,t.id,'mcq','Which region of India is a global biodiversity hotspot?','easy','draft',1,0,'en' from public.topics t join public.subjects s on s.id=t.subject_id where s.track='gk_gs' and t.slug='environment';
