insert into private.question_solutions(question_id,explanation) values ('8aa95653-5167-487e-8b21-24cb34a280bb','The Western Ghats (with Sri Lanka) is one of the world''s biodiversity hotspots. India''s others are the Himalaya, Indo-Burma and Sundaland.');
